// Integrates the Lorenz system, a classic example of chaotic dynamics.
// The precision and integration method are chosen when configuring
// with CMake (see config.h.in).

#include <config.h> // generated by CMake

#include <array>
#include <cassert>
#include <print>

#ifdef LORENZ_USE_FLOAT
using real = float;
#else
using real = double;
#endif

using State = std::array<real, 3>;

State lorenz(const State& s)
{
    const real sigma = 10, rho = 28, beta = real(8) / 3;
    return {sigma * (s[1] - s[0]), s[0] * (rho - s[2]) - s[1], s[0] * s[1] - beta * s[2]};
}

State add(const State& a, real h, const State& b)
{
    return {a[0] + h * b[0], a[1] + h * b[1], a[2] + h * b[2]};
}

State step(const State& s, real h)
{
#ifdef LORENZ_USE_RK4
    const State k1 = lorenz(s);
    const State k2 = lorenz(add(s, h / 2, k1));
    const State k3 = lorenz(add(s, h / 2, k2));
    const State k4 = lorenz(add(s, h, k3));
    State r;
    for (std::size_t i = 0; i < 3; ++i)
        r[i] = s[i] + h / 6 * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]);
    return r;
#else
    return add(s, h, lorenz(s));
#endif
}

int main()
{
    std::println("Lorenz {} ({} build)", LORENZ_VERSION, LORENZ_BUILD_TYPE);
    std::println("Compiler   : {} on {}", LORENZ_COMPILER, LORENZ_SYSTEM);
    std::println("Precision  : {}", sizeof(real) == 4 ? "float" : "double");
#ifdef LORENZ_USE_RK4
    std::println("Integrator : RK4");
#else
    std::println("Integrator : Euler");
#endif

    // assert() is active in Debug builds and removed in Release builds
    // (CMake adds -DNDEBUG for Release).
    assert(sizeof(real) >= 4);

    State s = {1, 1, 1};
    const real h = real(0.001);

    for (int i = 1; i <= 20000; ++i)
    {
        s = step(s, h);
        if (i % 4000 == 0)
            std::println("t = {:4.1f}: ({:9.4f}, {:9.4f}, {:9.4f})", static_cast<real>(i) * h, s[0],
                         s[1], s[2]);
    }

    std::println("\nTry reconfiguring with -DLORENZ_USE_FLOAT=ON or -DLORENZ_INTEGRATOR=euler\n"
                 "and compare - chaotic systems are very sensitive to small errors.");

    return 0;
}
